#!/usr/bin/env node
/**
 * Is dist/overlays.mjs fresh? (docs/M8-DESIGN.md §10.6, D34) Needs no system data, so CI runs it.
 *   node tools/dist-check.mjs [--root <library folder>]   (or DS_AUTO_LIBRARY; default: this file's ../)
 * tools/build.mjs writes the first line of dist/overlays.mjs:
 *   // Generated by tools/build.mjs from src/overlays (stef-ds-automation <v>, Draw Steel <sv>). src-sha256: <hex>. Do not edit.
 * This recomputes <hex> over src/overlays and checks that <v> is the version in module.json. Exit 1 on a mismatch
 * (rebuild with `node tools/build.mjs`, which needs the system index in .cache/).
 * The hash: SHA-256 over every src/overlays/**\/*.json, sorted by its path relative to src/overlays ("/" separators,
 * code-unit order); per file the path, a NUL, the bytes with CRLF/CR normalized to LF, a NUL. A Windows checkout and
 * CI agree (REPO/.gitattributes sets `*.json text eol=lf` too).
 */
import crypto from "node:crypto";
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

const HERE = path.dirname(fileURLToPath(import.meta.url));

/** The header line of dist/overlays.mjs (build.mjs writes it, this file parses it). */
export const headerLine = ({ version, system, hash }) =>
  `// Generated by tools/build.mjs from src/overlays (stef-ds-automation ${version}, Draw Steel ${system}). src-sha256: ${hash}. Do not edit.`;
const HEADER_RE = /^\/\/ Generated by tools\/build\.mjs from src\/overlays \(stef-ds-automation (\S+), Draw Steel (\S+)\)\. src-sha256: ([0-9a-f]{64})\. Do not edit\.$/;

/** Parse a header line: {version, system, hash} or null. */
export function parseHeader(line) {
  const m = HEADER_RE.exec(String(line ?? "").trim());
  return m ? { version: m[1], system: m[2], hash: m[3] } : null;
}

/** Relative paths ("/" separators) of the overlay sources under `dir`, sorted. */
function overlayFiles(dir, base = dir, out = []) {
  for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
    const p = path.join(dir, e.name);
    if (e.isDirectory()) overlayFiles(p, base, out);
    else if (e.isFile() && e.name.endsWith(".json")) out.push(path.relative(base, p).split(path.sep).join("/"));
  }
  return out;
}

/** SHA-256 (hex) of the library's src/overlays (see the header comment). */
export function srcHash(root) {
  const src = path.join(root, "src", "overlays");
  const files = overlayFiles(src).sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
  const h = crypto.createHash("sha256");
  for (const rel of files) {
    const text = fs.readFileSync(path.join(src, ...rel.split("/")), "utf8").replace(/\r\n?/g, "\n");
    h.update(rel, "utf8");
    h.update("\0");
    h.update(text, "utf8");
    h.update("\0");
  }
  return { hash: h.digest("hex"), files: files.length };
}

/** Check one library folder. Returns {ok, problems, header, hash, files}. */
export function checkDist(root) {
  const problems = [];
  const distFile = path.join(root, "dist", "overlays.mjs");
  let header = null;
  if (!fs.existsSync(distFile)) problems.push("dist/overlays.mjs does not exist (run node tools/build.mjs)");
  else {
    const first = fs.readFileSync(distFile, "utf8").split(/\r?\n/, 1)[0];
    header = parseHeader(first);
    if (!header) problems.push(`dist/overlays.mjs: no src-sha256 header (an older build?): ${first.slice(0, 120)}`);
  }
  let version = null;
  try {
    version = JSON.parse(fs.readFileSync(path.join(root, "module.json"), "utf8")).version;
  } catch (err) {
    problems.push(`module.json: ${err.message}`);
  }
  const { hash, files } = srcHash(root);
  if (header) {
    if (version && header.version !== version) problems.push(`dist/overlays.mjs was built for ${header.version}, module.json says ${version}`);
    if (header.hash !== hash) problems.push(`src/overlays changed since the build (src-sha256 ${hash.slice(0, 12)}…, dist has ${header.hash.slice(0, 12)}…)`);
  }
  return { ok: !problems.length, problems, header, hash, files };
}

function rootFromArgs(argv) {
  const i = argv.indexOf("--root");
  if (i >= 0 && argv[i + 1]) return path.resolve(argv[i + 1]);
  if (process.env.DS_AUTO_LIBRARY) return path.resolve(process.env.DS_AUTO_LIBRARY);
  return path.resolve(HERE, "..");
}

if (process.argv[1] && import.meta.url === pathToFileURL(path.resolve(process.argv[1])).href) {
  const root = rootFromArgs(process.argv.slice(2));
  const r = checkDist(root);
  for (const p of r.problems) console.log(`ERROR ${p}`);
  if (r.ok) console.log(`dist fresh: stef-ds-automation ${r.header.version}, ${r.files} overlay files, src-sha256 ${r.hash.slice(0, 12)}…`);
  else console.log("dist stale: run node tools/build.mjs (needs the system index: node tools/index-system.mjs)");
  process.exit(r.ok ? 0 : 1);
}
